  "votes": [
    {
      "item": "i01",
      "choice": "v1",
      "reason": "Le point relatif au 3, rue Ernest-Piché est marqué « REPORTÉ » à la page 2, et la résolution 089-2026 confirme son report à une séance ultérieure, sans décision sur la dérogation."
    },
    {
      "item": "i02",
      "choice": "v1",
      "reason": "La résolution 102-2026 autorise expressément, à la page 10, la signature de l’acte de servitude de passage et de droit de premier refus pour le lot 6 164 031."
    },
    {
      "item": "i03",
      "choice": "v1",
      "reason": "La résolution 111-2026 accorde à la page 20 la dérogation permettant la conversion de l’abri d’auto en garage privé attenant au 2, rue Garbin."
    },
    {
      "item": "i04",
      "choice": "v1",
      "reason": "La résolution 112-2026 accorde explicitement, à la page 21, la dérogation concernant le lotissement du lot d’angle 6 621 589 avec une largeur de 27,20 mètres."
    },
    {
      "item": "i05",
      "choice": "v1",
      "reason": "La résolution 113-2026 approuve à la page 22 la subdivision d’une parcelle du lot 6 141 355 dans le cadre du réaménagement du pont de la rivière Ontaritzi."
    },
    {
      "item": "i06",
      "choice": "v1",
      "reason": "La résolution 115-2026 modifie à la page 23 l’entente de développement avec Groupe Castella 2 inc. pour reporter au 31 octobre 2026 la fin des travaux de prolongement de l’avenue des Catherine."
    },
    {
      "item": "i07",
      "choice": "v1",
      "reason": "La résolution 116-2026 modifie à la page 24 les conditions d’approbation du PIIA visé par la résolution 344-2024 en exigeant une garantie de 35 000 $ pour chacune des phases 1A et 1B."
    },
    {
      "item": "i08",
      "choice": "v1",
      "reason": "La page 24 atteste un avis de motion actuel visant la modification du zonage 1259-2014 pour les limites, les usages et les normes des zones 115-H et 145-H."
    },
    {
      "item": "i09",
      "choice": "v1",
      "reason": "Le titre cité figure à la page 24 au début de la résolution 117-2026, dont le dispositif à la page 25 adopte le premier projet APR-423-2026, distinct de l’avis de motion."
    },
    {
      "item": "i10",
      "choice": "v1",
      "reason": "La résolution 124-2026 autorise à la page 29 la location d’un bâtiment et d’un emplacement à Yogi Nomade, soit un acte foncier explicite même si sa destination est récréative."
    },
    {
      "item": "i11",
      "choice": "v1",
      "reason": "La résolution 099-2026 engage expressément la Ville, à la page 9, à amorcer les modifications réglementaires nécessaires à l’usage parc solaire, sans constituer un avis de motion ni une adoption de règlement."
    },
    {
      "item": "i12",
      "choice": "absent",
      "reason": "Cette proposition reprend exactement l’acte de location retenu sous i10, alors que la règle impose un rappel par unité distincte et ne crédite pas les doublons du même fait."
    }
  ]
}
